export function FileList({
  caption = "{{caption}}",
  rows = "{{rows}}",
  showDate = {{showDate}},
  density = "{{density}}",
  accent = "{{accent}}",
}) {
  const pad = density === "Compact" ? "4px 10px" : "8px 10px";
  const files = [
    { name: "brief.docx", size: "240 KB", date: "2026-08-14", label: "14 Aug" },
    { name: "budget.xlsx", size: "88 KB", date: "2026-08-12", label: "12 Aug" },
    { name: "roadmap.pdf", size: "640 KB", date: "2026-08-09", label: "9 Aug" },
    { name: "photo.jpg", size: "1.1 MB", date: "2026-08-02", label: "2 Aug" },
  ].slice(0, Number(rows));
  const cell = { textAlign: "left", padding: pad, borderBottom: "1px solid #24143014" };
  return (
    <table style={{ borderCollapse: "collapse", width: 360, font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <caption style={{ textAlign: "left", fontWeight: 700, paddingBottom: 8 }}>{caption}</caption>
      <thead>
        <tr>
          <th scope="col" style={{ ...cell, color: "#24143099", fontWeight: 600, fontSize: 12 }}>Name</th>
          <th scope="col" style={{ ...cell, color: "#24143099", fontWeight: 600, fontSize: 12 }}>Size</th>
          {showDate && <th scope="col" style={{ ...cell, color: "#24143099", fontWeight: 600, fontSize: 12 }}>Modified</th>}
        </tr>
      </thead>
      <tbody>
        {files.map((f) => (
          <tr key={f.name}>
            <td style={cell}><span style={{ display: "inline-block", width: 8, height: 8, borderRadius: 999, marginRight: 8, background: accent }} />{f.name}</td>
            <td style={cell}>{f.size}</td>
            {showDate && <td style={cell}><time dateTime={f.date}>{f.label}</time></td>}
          </tr>
        ))}
      </tbody>
    </table>
  );
}
